-- Tracedown: Postgres schema. Generated by `python -m tracedown_server.storage.postgres`;
-- the server creates and migrates these tables itself on start, so applying this file is optional
-- (useful for review, or for a DBA who provisions schemas ahead of time).
-- Schema version 1. High-volume spans can live in ClickHouse instead (clickhouse.sql).

-- core: runs, spans, payloads, findings
CREATE TABLE IF NOT EXISTS schema_migrations (
    version     INTEGER PRIMARY KEY,
    applied_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    note        TEXT
);
CREATE TABLE IF NOT EXISTS runs (
    trace_id      TEXT PRIMARY KEY,
    project       TEXT NOT NULL,
    agent_name    TEXT,
    outcome       TEXT,
    error         TEXT,
    started_at    BIGINT,
    duration_ms   DOUBLE PRECISION,
    span_count    INTEGER,
    input_tokens  BIGINT,
    output_tokens BIGINT,
    models        JSONB,
    replay_of     TEXT,
    attributes    JSONB,
    profile       JSONB
);
CREATE INDEX IF NOT EXISTS runs_project_time ON runs(project, started_at DESC);
CREATE INDEX IF NOT EXISTS runs_agent_time ON runs(agent_name, started_at);
CREATE TABLE IF NOT EXISTS spans (
    project        TEXT NOT NULL,
    trace_id       TEXT NOT NULL,
    span_id        TEXT NOT NULL,
    parent_span_id TEXT,
    name           TEXT,
    kind           TEXT,
    start_time     BIGINT,
    end_time       BIGINT,
    status_code    TEXT,
    status_message TEXT,
    attributes     JSONB,
    input_digest   TEXT,
    output_digest  TEXT,
    PRIMARY KEY (trace_id, span_id)
);
CREATE INDEX IF NOT EXISTS spans_project_kind ON spans(project, kind, start_time);
CREATE TABLE IF NOT EXISTS payloads (
    project  TEXT NOT NULL,
    digest   TEXT NOT NULL,
    content  TEXT NOT NULL,
    PRIMARY KEY (project, digest)
);
CREATE TABLE IF NOT EXISTS trace_owner (
    trace_id  TEXT PRIMARY KEY,
    project   TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS findings (
    trace_id   TEXT PRIMARY KEY,
    report     JSONB NOT NULL,
    created_at BIGINT
);
INSERT INTO schema_migrations(version, note) VALUES (1, 'core tables') ON CONFLICT DO NOTHING;

-- settings (analytics)
CREATE TABLE IF NOT EXISTS settings (
    key    TEXT PRIMARY KEY,
    value  TEXT NOT NULL
);

-- drift
CREATE TABLE IF NOT EXISTS drift_reports (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    project     TEXT,
    agent       TEXT NOT NULL,
    dimension   TEXT NOT NULL,
    baseline    TEXT NOT NULL,
    candidate   TEXT NOT NULL,
    verdict     TEXT NOT NULL,
    severity    TEXT NOT NULL,
    created_at  BIGINT NOT NULL,
    report      TEXT NOT NULL,
    UNIQUE (project, agent, dimension, baseline, candidate)
);

-- incidents
CREATE TABLE IF NOT EXISTS incidents (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    project        TEXT,
    signature      TEXT NOT NULL,
    agent          TEXT,
    category       TEXT NOT NULL,
    target         TEXT,
    title          TEXT NOT NULL,
    root_cause     TEXT NOT NULL,
    suggested_fix  TEXT,
    status         TEXT NOT NULL DEFAULT 'open',
    severity       TEXT NOT NULL DEFAULT 'low',
    run_count      BIGINT NOT NULL DEFAULT 0,
    first_seen     BIGINT NOT NULL,
    last_seen      BIGINT NOT NULL,
    resolved_at    BIGINT,
    UNIQUE (project, signature)
);
CREATE TABLE IF NOT EXISTS incident_runs (
    incident_id  BIGINT NOT NULL,
    trace_id     TEXT NOT NULL,
    at           BIGINT NOT NULL,
    PRIMARY KEY (incident_id, trace_id)
);
CREATE TABLE IF NOT EXISTS incident_events (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    incident_id  BIGINT NOT NULL,
    at           BIGINT NOT NULL,
    kind         TEXT NOT NULL,
    detail       TEXT
);

-- notification hooks
CREATE TABLE IF NOT EXISTS hooks (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    project       TEXT,
    kind          TEXT NOT NULL,
    name          TEXT,
    config        TEXT NOT NULL,
    events        TEXT NOT NULL,
    min_severity  TEXT NOT NULL DEFAULT 'medium',
    enabled       BIGINT NOT NULL DEFAULT 1,
    created_at    BIGINT NOT NULL
);
CREATE TABLE IF NOT EXISTS hook_deliveries (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    hook_id   BIGINT NOT NULL,
    event     TEXT NOT NULL,
    at        BIGINT NOT NULL,
    ok        BIGINT NOT NULL,
    status    BIGINT,
    error     TEXT
);

-- users, roles and API keys
CREATE TABLE IF NOT EXISTS users (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email        TEXT NOT NULL UNIQUE,
    name         TEXT,
    org_role     TEXT NOT NULL DEFAULT 'member',
    sso_subject  TEXT,
    disabled     BIGINT NOT NULL DEFAULT 0,
    created_at   BIGINT NOT NULL,
    last_login   BIGINT
);
CREATE TABLE IF NOT EXISTS memberships (
    user_id  BIGINT NOT NULL,
    project  TEXT NOT NULL,
    role     TEXT NOT NULL,
    PRIMARY KEY (user_id, project)
);
CREATE TABLE IF NOT EXISTS api_keys (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name          TEXT,
    prefix        TEXT NOT NULL,
    key_hash      TEXT NOT NULL UNIQUE,
    project       TEXT NOT NULL,
    role          TEXT NOT NULL,
    created_by    TEXT,
    created_at    BIGINT NOT NULL,
    last_used_at  BIGINT,
    revoked_at    BIGINT
);

-- audit log
CREATE TABLE IF NOT EXISTS audit_log (
    seq        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    at         BIGINT NOT NULL,
    actor      TEXT NOT NULL,
    action     TEXT NOT NULL,
    resource   TEXT,
    project    TEXT,
    ip         TEXT,
    outcome    TEXT NOT NULL,
    detail     TEXT,
    prev_hash  TEXT NOT NULL,
    hash       TEXT NOT NULL
);

-- PII policies
CREATE TABLE IF NOT EXISTS pii_policies (
    project     TEXT PRIMARY KEY,
    policy      TEXT NOT NULL,
    updated_at  BIGINT NOT NULL,
    updated_by  TEXT
);
CREATE TABLE IF NOT EXISTS pii_events (
    project   TEXT NOT NULL,
    day       TEXT NOT NULL,
    detector  TEXT NOT NULL,
    count     BIGINT NOT NULL,
    PRIMARY KEY (project, day, detector)
);
